import{_ as s,I as t,o as r,c as d,b6 as i,j as o,J as e,w as h}from"./chunks/framework.COUcLbTA.js";const P=JSON.parse('{"title":"Spring Boot 电影推荐系统开发实战","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/stage-2/assignments/movie-recommendation-springboot/index.md","filePath":"zh-cn/stage-2/assignments/movie-recommendation-springboot/index.md"}'),p={name:"zh-cn/stage-2/assignments/movie-recommendation-springboot/index.md"},c={style:{margin:"32px 0"}};function b(g,a,k,u,m,f){const l=t("StepBar"),n=t("ClientOnly");return r(),d("div",null,[a[0]||(a[0]=i('<h1 id="spring-boot-电影推荐系统开发实战" tabindex="-1">Spring Boot 电影推荐系统开发实战 <a class="header-anchor" href="#spring-boot-电影推荐系统开发实战" aria-label="Permalink to “Spring Boot 电影推荐系统开发实战”">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to “概述”">​</a></h2><p>本实战项目要求你围绕一份真实的 PRD，使用 Spring Boot 完成一个带推荐能力的电影网站。这个项目的核心挑战在于：它不是简单的增删改查，而是需要你思考&quot;用户行为如何影响推荐结果&quot;以及&quot;推荐如何可解释&quot;。</p><p>这是 Stage 2 的综合实战环节。你将第一次接触&quot;内容 + 行为 + 推荐&quot;型产品的开发模式，这种模式在电商、内容平台、个性化 Feed 等场景中非常常见。</p><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to “前置知识”">​</a></h2><p>在开始本项目之前，你应该已经掌握以下内容：</p><ul><li>前端页面设计与组件库使用（<a href="./../../frontend/ui-design/">UI 设计</a>、<a href="./../../frontend/modern-component-library/">现代组件库</a>）</li><li>后端接口设计与开发（<a href="./../../backend/ai-interface-code/">接口代码编写</a>）</li><li>数据库基础与 Supabase（<a href="./../../backend/database-supabase/">从数据库到 Supabase</a>）</li><li>Git 工作流与部署（<a href="./../../backend/git-workflow/">Git 和 GitHub</a>、<a href="./../../backend/zeabur-deployment/">部署 Web 应用</a>）</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to “学习目标”">​</a></h2><p>完成本实战后，你将能够：</p><ol><li>阅读 PRD 并从中提取推荐系统的开发任务清单</li><li>使用 Spring Boot 搭建后端项目并实现 RESTful API</li><li>设计&quot;用户行为 → 推荐&quot;的完整数据链路</li><li>实现可解释的推荐逻辑</li><li>完成端到端联调，交付可演示的产品原型</li></ol><h2 id="项目简介" tabindex="-1">项目简介 <a class="header-anchor" href="#项目简介" aria-label="Permalink to “项目简介”">​</a></h2><p>你要构建的产品是一个带推荐能力的电影网站：</p><table tabindex="0"><thead><tr><th>功能</th><th>描述</th></tr></thead><tbody><tr><td><strong>浏览与搜索</strong></td><td>用户可以浏览和搜索电影</td></tr><tr><td><strong>评分与收藏</strong></td><td>用户可以给电影评分、添加收藏</td></tr><tr><td><strong>个性化推荐</strong></td><td>系统根据用户行为给出推荐结果</td></tr><tr><td><strong>管理后台</strong></td><td>管理员维护电影数据、查看推荐效果</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">PRD 入口</p><p>本项目的需求文档在 GitHub： <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/zh-cn/stage-2/assignments/movie-recommendation-springboot/PRD.md" target="_blank" rel="noreferrer">查看 PRD</a></p></div>',14)),o("div",c,[e(n,null,{default:h(()=>[e(l,{active:0,items:[{title:"需求分析",description:"阅读 PRD，明确推荐策略、行为数据和后台范围"},{title:"搭建骨架",description:"用 AI 生成列表页、详情页、推荐页和后台页"},{title:"迭代开发",description:"补充推荐逻辑、行为记录和后台管理"},{title:"联调上线",description:"端到端跑通，部署并准备演示"}]})]),_:1})]),a[1]||(a[1]=i(`<h2 id="第一部分-需求分析" tabindex="-1">第一部分：需求分析 <a class="header-anchor" href="#第一部分-需求分析" aria-label="Permalink to “第一部分：需求分析”">​</a></h2><h3 id="_1-1-阅读-prd" tabindex="-1">1.1 阅读 PRD <a class="header-anchor" href="#_1-1-阅读-prd" aria-label="Permalink to “1.1 阅读 PRD”">​</a></h3><p>打开 PRD 文档，重点回答以下问题：</p><ul><li>推荐策略是什么？第一版是否使用可解释版本（如基于评分相似度）？</li><li>用户行为数据要存哪些？（评分、收藏、浏览记录等）</li><li>管理员需要看哪些推荐效果指标？</li><li>页面清单是否完整？</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>如果以上问题没有明确答案，不要开始写代码。需求理解不清楚是导致返工的最常见原因。</p></div><h3 id="_1-2-确认系统架构" tabindex="-1">1.2 确认系统架构 <a class="header-anchor" href="#_1-2-确认系统架构" aria-label="Permalink to “1.2 确认系统架构”">​</a></h3><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; web[&quot;前端页面&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  web --&gt; auth[&quot;用户鉴权&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  web --&gt; movie[&quot;电影列表 / 详情&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  web --&gt; behavior[&quot;评分 / 收藏&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  behavior --&gt; reco[&quot;推荐逻辑&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  reco --&gt; db[&quot;数据库&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin[&quot;后台管理&quot;] --&gt; db</span></span></code></pre></div><h2 id="第二部分-搭建项目骨架" tabindex="-1">第二部分：搭建项目骨架 <a class="header-anchor" href="#第二部分-搭建项目骨架" aria-label="Permalink to “第二部分：搭建项目骨架”">​</a></h2><h3 id="_2-1-生成前端页面" tabindex="-1">2.1 生成前端页面 <a class="header-anchor" href="#_2-1-生成前端页面" aria-label="Permalink to “2.1 生成前端页面”">​</a></h3><p>提示词参考：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请基于当前 PRD，帮我生成一个 Spring Boot 电影推荐系统的前端骨架。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1. 页面包括：首页、电影列表、电影详情、推荐页、个人中心、后台管理</span></span>
<span class="line"><span>2. 先只生成页面结构和假数据，不接真实接口</span></span>
<span class="line"><span>3. 风格要像真实内容产品，而不是课堂 demo</span></span></code></pre></div><h3 id="_2-2-验证页面结构" tabindex="-1">2.2 验证页面结构 <a class="header-anchor" href="#_2-2-验证页面结构" aria-label="Permalink to “2.2 验证页面结构”">​</a></h3><p>逐项检查：</p><ul><li>[ ] 电影列表页支持搜索和筛选</li><li>[ ] 电影详情页包含评分和收藏按钮</li><li>[ ] 推荐页能展示推荐结果和推荐理由</li><li>[ ] 管理后台能展示电影数据和推荐效果</li></ul><h2 id="第三部分-迭代开发" tabindex="-1">第三部分：迭代开发 <a class="header-anchor" href="#第三部分-迭代开发" aria-label="Permalink to “第三部分：迭代开发”">​</a></h2><h3 id="_3-1-按模块推进" tabindex="-1">3.1 按模块推进 <a class="header-anchor" href="#_3-1-按模块推进" aria-label="Permalink to “3.1 按模块推进”">​</a></h3><ol><li><strong>Spring Boot 项目搭建</strong>：项目结构、数据库配置、基础 CRUD</li><li><strong>电影数据管理</strong>：电影列表、详情、搜索接口</li><li><strong>用户行为</strong>：评分、收藏接口，行为数据写入</li><li><strong>推荐逻辑</strong>：基于用户行为的推荐算法实现</li><li><strong>推荐展示</strong>：推荐结果展示，包含推荐理由</li><li><strong>管理后台</strong>：电影数据维护、推荐效果查看</li></ol><h3 id="_3-2-模块自检" tabindex="-1">3.2 模块自检 <a class="header-anchor" href="#_3-2-模块自检" aria-label="Permalink to “3.2 模块自检”">​</a></h3><table tabindex="0"><thead><tr><th>检查项</th><th>验证方法</th></tr></thead><tbody><tr><td>基础功能</td><td>列表、详情、评分、收藏是否闭环</td></tr><tr><td>推荐联动</td><td>用户行为是否影响推荐结果</td></tr><tr><td>推荐可解释性</td><td>用户能理解为什么被推荐这些电影</td></tr><tr><td>后台数据</td><td>管理员能查看电影数据和推荐效果</td></tr></tbody></table><h2 id="第四部分-联调与上线" tabindex="-1">第四部分：联调与上线 <a class="header-anchor" href="#第四部分-联调与上线" aria-label="Permalink to “第四部分：联调与上线”">​</a></h2><h3 id="_4-1-端到端测试" tabindex="-1">4.1 端到端测试 <a class="header-anchor" href="#_4-1-端到端测试" aria-label="Permalink to “4.1 端到端测试”">​</a></h3><p>至少验证以下场景：</p><ul><li>浏览电影 → 评分 → 收藏 → 查看推荐页，确认推荐结果发生变化</li><li>管理员登录 → 添加电影 → 查看推荐效果统计</li></ul><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to “交付物”">​</a></h2><p>完成本项目后，你需要提交以下内容：</p><ul><li>[ ] 可访问的线上演示链接</li><li>[ ] 源码仓库链接（含 README）</li><li>[ ] PRD 文档</li><li>[ ] 核心页面截图（电影列表、电影详情、推荐页、管理后台）</li><li>[ ] 60 秒演示视频</li></ul><h2 id="评分标准" tabindex="-1">评分标准 <a class="header-anchor" href="#评分标准" aria-label="Permalink to “评分标准”">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>基本要求</th><th>进阶要求</th></tr></thead><tbody><tr><td>PRD 对齐</td><td>页面、功能、数据结构基本符合 PRD</td><td>能清晰说明设计决策</td></tr><tr><td>产品闭环</td><td>浏览 → 评分 → 收藏 → 推荐可跑通</td><td>评分行为明显影响推荐结果</td></tr><tr><td>推荐质量</td><td>推荐结果合理、推荐理由可解释</td><td>支持多种推荐策略</td></tr><tr><td>后台能力</td><td>电影数据和推荐效果可查看</td><td>有推荐准确率等统计指标</td></tr><tr><td>工程完整度</td><td>前端、Spring Boot 后端、数据库链路已接通</td><td>推荐接口有缓存或性能优化</td></tr></tbody></table><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to “参考资料”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">UI 设计</a></li><li><a href="./../../frontend/modern-component-library/">使用现代组件库更新你的界面</a></li><li><a href="./../../backend/database-supabase/">从数据库到 Supabase</a></li><li><a href="./../../backend/ai-interface-code/">大模型辅助编写接口代码与接口文档</a></li><li><a href="./../../backend/git-workflow/">Git 和 GitHub 工作流</a></li><li><a href="./../../backend/zeabur-deployment/">如何部署 Web 应用</a></li></ul>`,30))])}const E=s(p,[["render",b]]);export{P as __pageData,E as default};
